                "   SELECT i_id, i_title, a_fname, a_lname " +
                "     FROM item, author " +
                "    WHERE lower(i_subject) = lower(?) " +
                "      AND i_pub_date > to_timestamp(?, 'YYYY-MM-DD HH24:MI:SS') " +
                "      AND i_a_id = a_id  " +
                " ORDER BY i_pub_date desc, i_title asc");

