                //  printMessage(query.toString());
                stmt.executeUpdate(query.toString()); //NOT REACHED
            }
            // clause 2.4.2.2 (dot 9)
            total_amount *= (1 - c_discount) * (1 + w_tax + d_tax);
            // clause 2.4.2.2 (dot 10)
