    public static String DigSyl(int d, int n) {
        String s = "";
        if (n == 0) {
            return (DigSyl(d));
        }
        for (; n > 0; n--) {
            int c = d % 10;
            s = digS[c] + s;
            d = d / 10;
        }
        return (s);
    }

    private static String DigSyl(int d) {
        String s = "";
        for (; d != 0; d = d / 10) {
            int c = d % 10;
            s = digS[c] + s;
        }
        return (s);
    }

